#include <stdio.h>

int count_digits(int n) {
    int count = 0;
    while (n > 0) {
        count++;
        n /= 10;
    }
    return count;
}

int main() {
    printf("%d %d\n", count_digits(4096), count_digits(123456789));
    return 0;
}
